    [Xunit.Fact]
    public static void TestAShiftedFontIsCaughtByAgreementAlone() {
        emon.Port.Cells rep = emon.Port.NewCells();
        HfDoc(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-shift.pdf"), emon.Testport.TestFile("fusion/health/pdf/tl-broken-shift.ocr"), 0, rep);
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 0), 5, "tl-broken-shift: five fonts on page 1");
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 1), 5, "tl-broken-shift: without OCR every one is trusted (P7.0 cannot tell)");
        HfDoc(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-shift.pdf"), emon.Testport.TestFile("fusion/health/pdf/tl-broken-shift.ocr"), 1, rep);
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 0), 5, "tl-broken-shift: five fonts");
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 1), 4, "tl-broken-shift: with OCR four are trusted");
        emon.Testport.AssertThat(emon.Port.CellsAt(rep, 2) < 300, "tl-broken-shift: the shifted font is under 300");
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 7), 0, "tl-broken-shift: it agrees on nothing");
        emon.Testport.AssertThat(emon.Port.CellsAt(rep, 5) >= 300, "tl-broken-shift: with groups to count");
    }
    [Xunit.Fact]
    public static void TestAnUnmappedFontIsCaughtWithOrWithoutOcr() {
        emon.Port.Cells rep = emon.Port.NewCells();
        HfDoc(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), emon.Testport.TestFile("fusion/health/pdf/tl-broken-unmapped.ocr"), 0, rep);
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 1), 4, "tl-broken-unmapped: four of five fonts are trusted without OCR");
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 2), 34, "tl-broken-unmapped: the broken one is P7.0's 34");
        HfDoc(emon.Testport.TestFile("corpus/synth/pdf/tl-broken-unmapped.pdf"), emon.Testport.TestFile("fusion/health/pdf/tl-broken-unmapped.ocr"), 1, rep);
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 1), 4, "tl-broken-unmapped: and with OCR");
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 2), 34, "tl-broken-unmapped: still 34: no letters to count");
    }
    [Xunit.Fact]
    public static void TestFontsThatLoseGlyphsStayAsTheTextLayerScoredThem() {
        // the Devanagari fonts whose ToUnicode has no matras (P7.0, D240): with OCR in, the same scores; the engine reads none of it
        emon.Port.Cells rep = emon.Port.NewCells();
        HfDoc(emon.Testport.TestFile("corpus/synth/pdf/script-devanagari.pdf"), emon.Testport.TestFile("fusion/health/pdf/script-devanagari.ocr"), 1, rep);
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 2), 616, "script-devanagari: P7.0's");
        HfDoc(emon.Testport.TestFile("corpus/synth/pdf/script-mixed.pdf"), emon.Testport.TestFile("fusion/health/pdf/script-mixed.ocr"), 1, rep);
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 2), 201, "script-mixed: P7.0's");
        emon.Testport.AssertEq(emon.Port.CellsAt(rep, 1), 11, "script-mixed: the same fonts trusted");
    }
